import https from 'https';

const PLAYLIST_ID = 'PLdo9RWRvrooWkoGsBYdr0D2cclU_NWGCk';

function get(url, headers = {}) {
  return new Promise((resolve, reject) => {
    const opts = {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36',
        'Accept-Language': 'he-IL,he;q=0.9,en;q=0.8',
        ...headers
      }
    };
    https.get(url, opts, (res) => {
      let data = '';
      res.on('data', d => data += d);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

function extractVideoIds(html) {
  const ids = new Set();
  const re = /"videoId":"([a-zA-Z0-9_-]{11})"/g;
  let m;
  while ((m = re.exec(html)) !== null) ids.add(m[1]);
  return [...ids];
}

async function getVideoTitle(html) {
  const m = html.match(/"title":\{"runs":\[{"text":"([^"]+)"/);
  return m ? m[1] : 'ללא כותרת';
}

async function getCaptionUrl(videoId) {
  const html = await get(`https://www.youtube.com/watch?v=${videoId}`);
  const m = html.match(/"captionTracks":\[(\{"baseUrl":"[^"]+?"name":\{"simpleText":"[^"]+?"\})/);
  if (!m) return null;
  const urlMatch = m[1].match(/"baseUrl":"([^"]+)"/);
  if (!urlMatch) return null;
  return urlMatch[1].replace(/\\u0026/g, '&');
}

async function getTranscript(captionUrl) {
  const xml = await get(captionUrl);
  const texts = [];
  const re = /<text[^>]*>([^<]+)<\/text>/g;
  let m;
  while ((m = re.exec(xml)) !== null) {
    texts.push(m[1].replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"'));
  }
  return texts.join(' ');
}

async function main() {
  console.log('מוריד פלייליסט...');
  const playlistHtml = await get(`https://www.youtube.com/playlist?list=${PLAYLIST_ID}`);
  const ids = extractVideoIds(playlistHtml);
  console.log(`נמצאו ${ids.length} סרטונים`);

  let allTranscripts = '';
  let count = 0;

  for (const id of ids) {
    try {
      const captionUrl = await getCaptionUrl(id);
      if (!captionUrl) {
        console.log(`[${id}] אין כתוביות`);
        continue;
      }
      const transcript = await getTranscript(captionUrl);
      if (!transcript.trim()) {
        console.log(`[${id}] כתוביות ריקות`);
        continue;
      }
      allTranscripts += `\n\n--- פרק: https://youtube.com/watch?v=${id} ---\n${transcript}`;
      count++;
      console.log(`[${count}/${ids.length}] ${id} - ${transcript.substring(0, 60)}...`);
      await new Promise(r => setTimeout(r, 300));
    } catch (e) {
      console.log(`[${id}] שגיאה: ${e.message}`);
    }
  }

  const fs = await import('fs');
  fs.writeFileSync('/workspace/agent/ma_batafkid_transcripts.txt', allTranscripts, 'utf8');
  console.log(`\nסיום! ${count} פרקים נשמרו ל-ma_batafkid_transcripts.txt`);
}

main().catch(console.error);

