import { createRequire } from 'module';
const require = createRequire(import.meta.url);
const { YoutubeTranscript } = require('youtube-transcript');
import { writeFileSync } from 'fs';

const PLAYLIST_ID = 'PLdo9RWRvrooWkoGsBYdr0D2cclU_NWGCk';

// Get video IDs from playlist
async function getPlaylistVideoIds() {
  const { execSync } = await import('child_process');
  const html = execSync(`curl -s "https://www.youtube.com/playlist?list=${PLAYLIST_ID}"`).toString();
  const ids = new Set();
  const re = /"videoId":"([a-zA-Z0-9_-]{11})"/g;
  let m;
  while ((m = re.exec(html)) !== null) ids.add(m[1]);
  return [...ids];
}

async function getVideoTitle(videoId) {
  const { execSync } = await import('child_process');
  try {
    const html = execSync(`curl -s "https://www.youtube.com/watch?v=${videoId}"`).toString();
    const m = html.match(/<title>([^<]*)<\/title>/);
    return m ? m[1].replace(' - YouTube', '').trim() : videoId;
  } catch { return videoId; }
}

async function main() {
  console.log('מוריד רשימת פרקים...');
  const ids = await getPlaylistVideoIds();
  console.log(`נמצאו ${ids.length} פרקים`);

  let output = `תמלולי פודקאסט "מה בתפקיד"\n${'='.repeat(50)}\n`;
  let success = 0;

  for (let i = 0; i < ids.length; i++) {
    const id = ids[i];
    try {
      const [transcript, title] = await Promise.all([
        YoutubeTranscript.fetchTranscript(id, { lang: 'iw' }).catch(() =>
          YoutubeTranscript.fetchTranscript(id).catch(() => null)
        ),
        getVideoTitle(id)
      ]);

      if (!transcript || transcript.length === 0) {
        console.log(`[${i+1}/${ids.length}] ${id} - אין תמלול`);
        continue;
      }

      const text = transcript.map(t => t.text).join(' ');
      output += `\n\n--- פרק ${i+1}: ${title} ---\n`;
      output += `קישור: https://youtube.com/watch?v=${id}\n\n`;
      output += text;
      success++;
      console.log(`[${i+1}/${ids.length}] ✓ ${title.substring(0, 60)}`);

      await new Promise(r => setTimeout(r, 400));
    } catch (e) {
      console.log(`[${i+1}/${ids.length}] ${id} - שגיאה: ${e.message.substring(0, 50)}`);
    }
  }

  writeFileSync('/workspace/agent/ma_batafkid_transcripts.txt', output, 'utf8');
  console.log(`\nסיום! ${success} פרקים נשמרו.`);
}

main().catch(console.error);

